@Bean
RestClient speechClient(RestClient.Builder builder,
        @Value("${elevenlabs.api-key}") String apiKey) {
    HttpClient http = HttpClient.newBuilder()
            .connectTimeout(Duration.ofSeconds(3)).build();
    var factory = new JdkClientHttpRequestFactory(http);
    factory.setReadTimeout(Duration.ofSeconds(10));
    return builder.baseUrl("https://api.elevenlabs.io")
            .requestFactory(factory)
            .defaultHeader("xi-api-key", apiKey).build();
}

record SpeechRequest(String text, String model_id) {}

ResponseEntity<byte[]> upstream = speechClient.post()
        .uri("/v1/text-to-speech/{voice}?output_format=mp3_44100_128", voiceId)
        .contentType(MediaType.APPLICATION_JSON)
        .body(new SpeechRequest(text, "eleven_multilingual_v2"))
        .retrieve().toEntity(byte[].class);

MediaType type = upstream.getHeaders().getContentType();
byte[] audio = upstream.getBody();
if (type == null || !"audio".equals(type.getType())
        || audio == null || audio.length == 0) {
    throw new IllegalStateException("Provider returned no audio");
}
return ResponseEntity.ok().contentType(type).body(audio);
